1	=========== cli.ts ===========
2	     1	/**
3	     2	 * The `claim-office` command: MHPCO's counter clerk.
4	     3	 *
5	     4	 * This module is an adapter and owns no ruling of the office's, not even how a
6	     5	 * scenario is worked through. It carries a scenario in from stdin, hands it to
7	     6	 * the office, and carries the answers back out to stdout. A scenario the office
8	     7	 * refuses ends the same way every refusal does: the clerk writes the reason to
9	     8	 * stderr and reports failure, leaving stdout empty.
10	     9	 *
11	    10	 * Everything this module knows is the shape of the paperwork — the JSON the
12	    11	 * office is addressed in and answers in, and how a refusal is reported at a
13	    12	 * command line. The rulings behind the answers are made elsewhere.
14	    13	 */
15	    14	
16	    15	import { readFileSync } from "node:fs";
17	    16	import { runScenario, type Scenario } from "./scenario.js";
18	    17	
19	    18	/** The clerk takes the whole of stdin as one scenario document. */
20	    19	const STDIN = 0;
21	    20	
22	    21	function main(): void {
23	    22	  const scenario = JSON.parse(readFileSync(STDIN, "utf8")) as Scenario;
24	    23	  process.stdout.write(JSON.stringify({ results: runScenario(scenario) }));
25	    24	}
26	    25	
27	    26	try {
28	    27	  main();
29	    28	} catch (error) {
30	    29	  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
31	    30	  process.exit(1);
32	    31	}
33	=========== scenario.ts ===========
34	     1	/**
35	     2	 * A scenario put to MHPCO across the counter: one customer, and a sequence of
36	     3	 * steps the office works through in order.
37	     4	 *
38	     5	 * This module owns one ruling of the office's: what it means to put steps to
39	     6	 * MHPCO in sequence. A quote writes a policy the office keeps on file under the
40	     7	 * step that asked for it, so that a later claim can name it; writing a contract
41	     8	 * advances the customer's standing, so the next quote is rated against it; and
42	     9	 * settling a claim consumes part of that policy's cap, so the office keeps the
43	    10	 * settled policy on file in place of the old one. A claim naming a step that
44	    11	 * wrote no policy is one the office refuses outright.
45	    12	 *
46	    13	 * It is kept apart from the `claim-office` command because that only carries
47	    14	 * the scenario in from the outside world and the answers back out: how MHPCO
48	    15	 * works through a sequence of steps is the office's ruling and would stand
49	    16	 * unchanged if the scenario arrived by some other means entirely.
50	    17	 */
51	    18	
52	    19	import {
53	    20	  claim,
54	    21	  createPolicy,
55	    22	  type Customer,
56	    23	  type Incident,
57	    24	  type Item,
58	    25	  type Policy,
59	    26	} from "./claim-office.js";
60	    27	import { afterWritingAContract } from "./customer-standing.js";
61	    28	
62	    29	/** A step asking MHPCO what it would charge to insure a list of items. */
63	    30	export interface QuoteStep {
64	    31	  readonly op: "quote";
65	    32	  readonly items: readonly Item[];
66	    33	}
67	    34	
68	    35	/** A step reporting damage against the policy an earlier quote step wrote. */
69	    36	export interface ClaimStep {
70	    37	  readonly op: "claim";
71	    38	  readonly policy: number;
72	    39	  readonly incident: Incident;
73	    40	}
74	    41	
75	    42	export type Step = QuoteStep | ClaimStep;
76	    43	
77	    44	/** A whole scenario: the one customer it concerns, and the steps to work through. */
78	    45	export interface Scenario {
79	    46	  readonly customer: { readonly yearsWithMHPCO: number };
80	    47	  readonly steps: readonly Step[];
81	    48	}
82	    49	
83	    50	/** What MHPCO answers to a quote step. */
84	    51	export interface QuoteResult {
85	    52	  readonly premium: number;
86	    53	}
87	    54	
88	    55	/** What MHPCO answers to a claim step. */
89	    56	export interface ClaimResult {
90	    57	  readonly payout: number;
91	    58	  readonly remainingCap: number;
92	    59	}
93	    60	
94	    61	export type StepResult = QuoteResult | ClaimResult;
95	    62	
96	    63	/**
97	    64	 * The office's counter as a scenario is worked through: the customer as their
98	    65	 * standing stands right now, and the policies written so far, on file under the
99	    66	 * step that asked for each.
100	    67	 */
101	    68	interface Counter {
102	    69	  customer: Customer;
103	    70	  readonly policies: Map<number, Policy>;
104	    71	}
105	    72	
106	    73	/**
107	    74	 * A customer arriving at the counter holds no contracts with MHPCO yet: only
108	    75	 * the contracts written during the scenario count towards their standing.
109	    76	 */
110	    77	function arrivingAtTheCounter(customer: Scenario["customer"]): Customer {
111	    78	  return { yearsWithMHPCO: customer.yearsWithMHPCO, previousContracts: 0 };
112	    79	}
113	    80	
114	    81	/**
115	    82	 * Writes a policy for the step's items and keeps it on file under that step, so
116	    83	 * a later claim can name it; the contract also advances the customer's standing
117	    84	 * for the steps that follow.
118	    85	 */
119	    86	function quoteStep(counter: Counter, step: QuoteStep, stepIndex: number): QuoteResult {
120	    87	  const policy = createPolicy(counter.customer, step.items);
121	    88	  counter.policies.set(stepIndex, policy);
122	    89	  counter.customer = afterWritingAContract(counter.customer);
123	    90	  return { premium: policy.premium };
124	    91	}
125	    92	
126	    93	/**
127	    94	 * Settles the step's damage report against the policy the named step wrote, and
128	    95	 * keeps the settled policy on file in its place — the claim has consumed part
129	    96	 * of its cap, and later claims are settled against what is left.
130	    97	 */
131	    98	function claimStep(counter: Counter, step: ClaimStep): ClaimResult {
132	    99	  const policy = counter.policies.get(step.policy);
133	   100	  if (policy === undefined) {
134	   101	    throw new Error(`step ${step.policy} did not create a policy`);
135	   102	  }
136	   103	  const settlement = claim(policy, step.incident);
137	   104	  counter.policies.set(step.policy, settlement.policy);
138	   105	  return { payout: settlement.payout, remainingCap: settlement.policy.remainingCap };
139	   106	}
140	   107	
141	   108	/**
142	   109	 * Works through a scenario step by step, answering each in turn. A step the
143	   110	 * office refuses ends the scenario there: the refusal stands for the whole of
144	   111	 * it, and no answers are given.
145	   112	 */
146	   113	export function runScenario(scenario: Scenario): readonly StepResult[] {
147	   114	  const counter: Counter = {
148	   115	    customer: arrivingAtTheCounter(scenario.customer),
149	   116	    policies: new Map<number, Policy>(),
150	   117	  };
151	   118	  return scenario.steps.map((step, stepIndex) =>
152	   119	    step.op === "quote" ? quoteStep(counter, step, stepIndex) : claimStep(counter, step),
153	   120	  );
154	   121	}
155	=========== claim-office.ts ===========
156	     1	import { policyBasePremium, policyInsuranceSum } from "./price-list.js";
157	     2	import { type Item } from "./item.js";
158	     3	import { itemRiskSurcharges } from "./item-risk.js";
159	     4	import { policyModifiers } from "./customer-standing.js";
160	     5	import { type Customer } from "./customer.js";
161	     6	import { roundPayoutInMHPCOFavour, roundPremiumInMHPCOFavour } from "./mhpco-rounding.js";
162	     7	import { capPayout, incidentReimbursement, payoutCap, type Incident } from "./claims.js";
163	     8	import { coverageOf } from "./policy-coverage.js";
164	     9	
165	    10	export type { Item, Customer };
166	    11	export type { Incident, Damage } from "./claims.js";
167	    12	
168	    13	/** A policy MHPCO has written: what it covers and what it was quoted for. */
169	    14	export interface Policy {
170	    15	  readonly premium: number;
171	    16	  readonly insuranceSum: number;
172	    17	  readonly items: readonly Item[];
173	    18	  /** What the office may still pay out on this policy. */
174	    19	  readonly remainingCap: number;
175	    20	}
176	    21	
177	    22	/**
178	    23	 * The settlement of one claim: what MHPCO pays, and the policy as it stands
179	    24	 * afterwards — a claim consumes part of the cap, so later claims against the
180	    25	 * same policy are settled against what is left, and `policy.remainingCap` is
181	    26	 * the one record of what the office may still pay out.
182	    27	 */
183	    28	export interface Settlement {
184	    29	  readonly payout: number;
185	    30	  readonly policy: Policy;
186	    31	}
187	    32	
188	    33	/**
189	    34	 * Writes a policy for the items the customer wishes to insure: the premium they
190	    35	 * owe, and the insurance sum the office's payouts are measured against.
191	    36	 */
192	    37	export function createPolicy(customer: Customer, items: readonly Item[]): Policy {
193	    38	  const insuranceSum = policyInsuranceSum(items);
194	    39	  return {
195	    40	    premium: quote(customer, items),
196	    41	    insuranceSum,
197	    42	    items,
198	    43	    remainingCap: payoutCap(insuranceSum),
199	    44	  };
200	    45	}
201	    46	
202	    47	/**
203	    48	 * Settles a damage report against a policy MHPCO has written, in the order the
204	    49	 * office settles it: what the report's damages come to under the reimbursement
205	    50	 * clauses, held down to what the policy's cap still allows, and rounded once at
206	    51	 * the end — the amount that actually leaves the office is the final payout, so
207	    52	 * the office's favour is taken on that and not on the uncapped total.
208	    53	 *
209	    54	 * Each of those rulings is made elsewhere; this function only knows their order.
210	    55	 */
211	    56	export function claim(policy: Policy, incident: Incident): Settlement {
212	    57	  const owed = incidentReimbursement(incident, coverageOf(policy.items));
213	    58	  const capped = capPayout(owed, policy.remainingCap);
214	    59	  return {
215	    60	    payout: roundPayoutInMHPCOFavour(capped.payout),
216	    61	    policy: { ...policy, remainingCap: capped.remainingCap },
217	    62	  };
218	    63	}
219	    64	
220	    65	/** MHPCO adds a flat processing fee to every premium, at the very end. */
221	    66	const PROCESSING_FEE_G = 5;
222	    67	
223	    68	/**
224	    69	 * Assembles the bill in the order the office bills it: the price-list base
225	    70	 * premium of the policy, the risk surcharges its individual items carry, the
226	    71	 * modifiers rated on the policy as a whole, and finally the processing fee.
227	    72	 *
228	    73	 * Each of those amounts is ruled on elsewhere; this function only knows the
229	    74	 * order they are applied in and that the total is rounded once, at the end.
230	    75	 */
231	    76	export function quote(customer: Customer, items: readonly Item[]): number {
232	    77	  const policyBase = policyBasePremium(items);
233	    78	  const premium =
234	    79	    policyBase +
235	    80	    itemRiskSurcharges(items) +
236	    81	    policyModifiers(customer, policyBase) +
237	    82	    PROCESSING_FEE_G;
238	    83	  return roundPremiumInMHPCOFavour(premium);
239	    84	}
240	=========== claims.ts ===========
241	     1	/**
242	     2	 * How MHPCO settles a damage report against a policy.
243	     3	 *
244	     4	 * This module owns the office's claims rulings: what it deducts from every
245	     5	 * damage event and what it is willing to reimburse. It knows nothing about
246	     6	 * premiums — a policy costs what it costs, and a claim pays what it pays.
247	     7	 */
248	     8	
249	     9	import { type Item } from "./item.js";
250	    10	
251	    11	/** A single damaged item in a damage report. */
252	    12	export interface Damage {
253	    13	  readonly itemType: string;
254	    14	  readonly amount: number;
255	    15	}
256	    16	
257	    17	/** A damage report submitted against a policy. */
258	    18	export interface Incident {
259	    19	  readonly cause: string;
260	    20	  readonly damages: readonly Damage[];
261	    21	}
262	    22	
263	    23	/** MHPCO reimburses the whole damage amount when no clause reduces it. */
264	    24	const FULL_SHARE = 1;
265	    25	const HALF_SHARE = 0.5;
266	    26	
267	    27	/**
268	    28	 * A reimbursement clause: a property of a damaged item the office has ruled on,
269	    29	 * and the share of the damage amount that clause grants.
270	    30	 */
271	    31	interface ReimbursementClause {
272	    32	  readonly appliesTo: (damagedItem: Item) => boolean;
273	    33	  readonly share: number;
274	    34	}
275	    35	
276	    36	/**
277	    37	 * A highly enchanted item is held to be beyond the office's ordinary means of
278	    38	 * restoration, so MHPCO reimburses only half of such a damage.
279	    39	 */
280	    40	const HALF_REIMBURSEMENT_FROM_ENCHANTMENT = 8;
281	    41	
282	    42	/** Dragon-forged goods are the office's pride; it reimburses them in full. */
283	    43	const FULLY_REIMBURSED_MATERIAL = "dragon";
284	    44	
285	    45	/**
286	    46	 * The office's register of reimbursement clauses. Each entry is an independent
287	    47	 * ruling: a further clause is added here, and the property or share of an
288	    48	 * existing one is revised here, without touching the deductible or the cap.
289	    49	 */
290	    50	const REIMBURSEMENT_CLAUSES: readonly ReimbursementClause[] = [
291	    51	  {
292	    52	    appliesTo: (damagedItem) =>
293	    53	      (damagedItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_FROM_ENCHANTMENT,
294	    54	    share: HALF_SHARE,
295	    55	  },
296	    56	  {
297	    57	    appliesTo: (damagedItem) => damagedItem.material === FULLY_REIMBURSED_MATERIAL,
298	    58	    share: FULL_SHARE,
299	    59	  },
300	    60	];
301	    61	
302	    62	/**
303	    63	 * The share of a damage amount MHPCO accepts before taking its deductible.
304	    64	 *
305	    65	 * When several clauses apply at once the office grants the least generous of
306	    66	 * them — a dragon-forged sword of enchantment 9 is reimbursed at half, not in
307	    67	 * full — and an item no clause speaks to is reimbursed in full.
308	    68	 */
309	    69	function acceptedShare(damagedItem: Item): number {
310	    70	  const shares = REIMBURSEMENT_CLAUSES.filter((clause) => clause.appliesTo(damagedItem)).map(
311	    71	    (clause) => clause.share,
312	    72	  );
313	    73	  return Math.min(FULL_SHARE, ...shares);
314	    74	}
315	    75	
316	    76	/**
317	    77	 * MHPCO will never pay out more than twice what a policy insures in total,
318	    78	 * however many claims are made against it.
319	    79	 */
320	    80	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
321	    81	
322	    82	/** The total MHPCO is willing to pay out over the life of a policy. */
323	    83	export function payoutCap(insuranceSum: number): number {
324	    84	  return insuranceSum * CAP_MULTIPLE_OF_INSURANCE_SUM;
325	    85	}
326	    86	
327	    87	/** How much of a reimbursement the cap lets through, and what is left of it. */
328	    88	export interface CappedPayout {
329	    89	  readonly payout: number;
330	    90	  readonly remainingCap: number;
331	    91	}
332	    92	
333	    93	/**
334	    94	 * Holds a reimbursement to what the policy's cap still allows: the office pays
335	    95	 * the lesser of what it owes and what its cap still permits, and whatever is
336	    96	 * left of the cap stands available to later claims against the same policy.
337	    97	 */
338	    98	export function capPayout(reimbursement: number, remainingCap: number): CappedPayout {
339	    99	  const payout = Math.min(reimbursement, remainingCap);
340	   100	  return { payout, remainingCap: remainingCap - payout };
341	   101	}
342	   102	
343	   103	/** MHPCO deducts a fixed excess from every damage event it settles. */
344	   104	const DEDUCTIBLE_G = 100;
345	   105	
346	   106	/**
347	   107	 * What MHPCO reimburses for a single damaged item: the share of the damage its
348	   108	 * clauses accept, less the deductible it keeps on every damage event.
349	   109	 */
350	   110	export function damageReimbursement(damage: Damage, damagedItem: Item): number {
351	   111	  if (damage.amount < 0) {
352	   112	    throw new Error(`a damage cannot be worth less than nothing: ${damage.amount}`);
353	   113	  }
354	   114	  return damage.amount * acceptedShare(damagedItem) - DEDUCTIBLE_G;
355	   115	}
356	   116	
357	   117	/**
358	   118	 * What MHPCO owes for a whole damage report, before its cap is applied: the
359	   119	 * office settles a report damage entry by damage entry and owes the sum, so a
360	   120	 * dragon attack on a sword and an amulet costs the office two deductibles, not
361	   121	 * one. Which insured item an entry refers to is a coverage question the caller
362	   122	 * answers; this ruling only knows that entries are settled one by one.
363	   123	 */
364	   124	export function incidentReimbursement(
365	   125	  incident: Incident,
366	   126	  insuredItemFor: (damage: Damage) => Item,
367	   127	): number {
368	   128	  return incident.damages.reduce(
369	   129	    (total, damage) => total + damageReimbursement(damage, insuredItemFor(damage)),
370	   130	    0,
371	   131	  );
372	   132	}
373	=========== policy-coverage.ts ===========
374	     1	/**
375	     2	 * Which insured item a damage entry is claiming against.
376	     3	 *
377	     4	 * This module owns one ruling of the office's: how a damage report is matched
378	     5	 * to the things a policy actually covers. Two decisions live here, and they are
379	     6	 * the office's to revise independently of how a claim is settled — what makes
380	     7	 * an insured item answer to a damage entry, and whether one insured item can be
381	     8	 * claimed for more than once in a single report.
382	     9	 *
383	    10	 * It is kept apart from the claims rulings because those price a damage once
384	    11	 * the damaged item is known; this one only decides *which* item that is. It is
385	    12	 * kept apart from the price list because that says what MHPCO insures at all,
386	    13	 * while this says how many of it *this* policy covers.
387	    14	 */
388	    15	
389	    16	import { type Damage } from "./claims.js";
390	    17	import { type Item } from "./item.js";
391	    18	
392	    19	/**
393	    20	 * Whether an insured item is one a damage entry can be claiming against. MHPCO
394	    21	 * identifies the damaged thing by its type alone: the report names what kind of
395	    22	 * item was damaged, and any insured item of that kind answers to it.
396	    23	 */
397	    24	function answersTo(insured: Item, damage: Damage): boolean {
398	    25	  return insured.type === damage.itemType;
399	    26	}
400	    27	
401	    28	/**
402	    29	 * Matches the damage entries of one report to the items a policy covers.
403	    30	 *
404	    31	 * A damaged item is claimed for once: two entries of the same type need two
405	    32	 * insured items of that type, so the matcher sets each item aside as it is
406	    33	 * claimed. A report naming more of a type than the policy covers — or a type it
407	    34	 * does not cover at all — is one the office refuses outright.
408	    35	 */
409	    36	export function coverageOf(insuredItems: readonly Item[]): (damage: Damage) => Item {
410	    37	  const unclaimed = [...insuredItems];
411	    38	  return (damage) => {
412	    39	    const index = unclaimed.findIndex((insured) => answersTo(insured, damage));
413	    40	    if (index === -1) {
414	    41	      throw new Error(`the policy does not cover a further item of type "${damage.itemType}"`);
415	    42	    }
416	    43	    const [claimed] = unclaimed.splice(index, 1);
417	    44	    return claimed;
418	    45	  };
419	    46	}
420	=========== price-list.ts ===========
421	     1	/**
422	     2	 * The MHPCO price list: what each insured thing costs before any modifier.
423	     3	 *
424	     4	 * This module owns catalogue knowledge — which item types the office recognises,
425	     5	 * what it insures each for and what base premium it charges — and, inseparably
426	     6	 * from it, the office's coverage ruling: MHPCO insures exactly what its price
427	     7	 * list names, so being absent from the catalogue *is* being uninsurable. All of
428	     8	 * it is one decision revised by one edit (list a broomstick, with its value and
429	     9	 * rate, and it becomes covered), which is why coverage is not a register of its
430	    10	 * own.
431	    11	 *
432	    12	 * It deliberately knows nothing about surcharges, discounts, the processing fee
433	    13	 * or rounding: those are underwriting policy and change for entirely different
434	    14	 * reasons. The building-block discount for alike components is likewise not
435	    15	 * here; this module only supplies the per-component rate the block rule prices
436	    16	 * against.
437	    17	 */
438	    18	
439	    19	import { type Item } from "./item.js";
440	    20	import { componentsBasePremium } from "./component-blocks.js";
441	    21	
442	    22	/** What the price list states about one main item type. */
443	    23	interface PriceListEntry {
444	    24	  readonly insuranceValueG: number;
445	    25	  readonly basePremiumG: number;
446	    26	}
447	    27	
448	    28	/**
449	    29	 * The MHPCO price list for main items. One entry per type the office
450	    30	 * recognises, stating everything the list says about it — so listing a
451	    31	 * broomstick, or revising what a sword is worth, is a single edit here.
452	    32	 */
453	    33	const MAIN_ITEM_PRICE_LIST: Readonly<Record<string, PriceListEntry>> = {
454	    34	  sword: { insuranceValueG: 1000, basePremiumG: 100 },
455	    35	  amulet: { insuranceValueG: 600, basePremiumG: 60 },
456	    36	  staff: { insuranceValueG: 800, basePremiumG: 80 },
457	    37	  potion: { insuranceValueG: 400, basePremiumG: 40 },
458	    38	};
459	    39	
460	    40	/**
461	    41	 * Components — runes, moonstones and their kin — are not listed individually on
462	    42	 * the main price list. MHPCO insures every component at the same value and
463	    43	 * charges one uniform rate per component, whatever a block costs.
464	    44	 */
465	    45	const COMPONENT_INSURANCE_VALUE_G = 250;
466	    46	const COMPONENT_BASE_PREMIUM_G = 25;
467	    47	
468	    48	/**
469	    49	 * What the price list says about a main item — and, in the same step, whether
470	    50	 * MHPCO covers it at all. The office insures only what its list names, so the
471	    51	 * missing entry *is* the refusal; splitting the lookup from the refusal would
472	    52	 * let the two drift apart.
473	    53	 */
474	    54	function mainItemEntry(item: Item): PriceListEntry {
475	    55	  const entry = MAIN_ITEM_PRICE_LIST[item.type];
476	    56	  if (entry === undefined) {
477	    57	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
478	    58	  }
479	    59	  return entry;
480	    60	}
481	    61	
482	    62	/**
483	    63	 * What MHPCO insures a single item for. Unlike the base premium, this value is
484	    64	 * untouched by any discount: the building block lowers what a policy costs, not
485	    65	 * what its components are insured for.
486	    66	 */
487	    67	export function itemInsuranceValue(item: Item): number {
488	    68	  return isComponent(item) ? COMPONENT_INSURANCE_VALUE_G : mainItemEntry(item).insuranceValueG;
489	    69	}
490	    70	
491	    71	/**
492	    72	 * What MHPCO insures a whole policy's items for: the sum of the items' own
493	    73	 * insurance values, untouched by any premium modifier or block discount. This
494	    74	 * is the quantity the office measures its payouts against.
495	    75	 */
496	    76	export function policyInsuranceSum(items: readonly Item[]): number {
497	    77	  return items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
498	    78	}
499	    79	
500	    80	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
501	    81	
502	    82	function isComponent(item: Item): boolean {
