536	     1	/**
537	     2	 * MHPCO's building-block rule for components.
538	     3	 *
539	     4	 * This module owns one underwriting policy: when a number of components
540	     5	 * qualifies as a building block, and what the office charges for it instead of
541	     6	 * the per-component rate. Two rulings live here, and they are the office's to
542	     7	 * revise: what counts as "alike" (MHPCO reads it as "of the same type", so two
543	     8	 * runes and a moonstone are not three alike components, and 3 runes with 3
544	     9	 * moonstones earn two separate blocks), and how large a block is and what it
545	    10	 * costs.
546	    11	 *
547	    12	 * It is kept apart from the price list because the two change for different
548	    13	 * reasons: the price of a rune is a catalogue revision, while the size, rate or
549	    14	 * the very meaning of a building block is a bundling decision the office makes
550	    15	 * on its own.
551	    16	 */
552	    17	
553	    18	import { type Item } from "./item.js";
554	    19	
555	    20	/** MHPCO offers a building block of exactly this many alike components. */
556	    21	const BLOCK_SIZE = 3;
557	    22	const BLOCK_BASE_PREMIUM_G = 60;
558	    23	
559	    24	/**
560	    25	 * MHPCO reads "alike" as "of the same type". Grouping components by type is
561	    26	 * therefore the office's ruling on what counts as alike, and the sizes of these
562	    27	 * groups are what the block rule is applied to.
563	    28	 */
564	    29	function alikeComponentGroupSizes(components: readonly Item[]): number[] {
565	    30	  const sizeByType = new Map<string, number>();
566	    31	  for (const component of components) {
567	    32	    sizeByType.set(component.type, (sizeByType.get(component.type) ?? 0) + 1);
568	    33	  }
569	    34	  return [...sizeByType.values()];
570	    35	}
571	    36	
572	    37	/**
573	    38	 * The base premium for a group of alike components: the block rate when the
574	    39	 * group is exactly a building block, the per-component rate otherwise.
575	    40	 */
576	    41	function alikeComponentsBasePremium(count: number, perComponentRateG: number): number {
577	    42	  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM_G : count * perComponentRateG;
578	    43	}
579	    44	
580	    45	/**
581	    46	 * The base premium MHPCO charges for a policy's components, at the given
582	    47	 * per-component rate. Components are priced per group of alike components, not
583	    48	 * per item: the office gathers the alike ones together first so that a building
584	    49	 * block can be recognised, then prices each group on its own.
585	    50	 */
586	    51	export function componentsBasePremium(
587	    52	  components: readonly Item[],
588	    53	  perComponentRateG: number,
589	    54	): number {
590	    55	  return alikeComponentGroupSizes(components).reduce(
591	    56	    (total, groupSize) => total + alikeComponentsBasePremium(groupSize, perComponentRateG),
592	    57	    0,
593	    58	  );
594	    59	}
