624	    17	/** A risky property of an item, and the surcharge MHPCO charges for it. */
625	    18	interface RiskRating {
626	    19	  readonly appliesTo: (item: Item) => boolean;
627	    20	  readonly surchargePercent: number;
628	    21	}
629	    22	
630	    23	/**
631	    24	 * The office's register of item risks. Each entry is an independent ruling:
632	    25	 * further risks are added here, and the rate of an existing one is revised
633	    26	 * here, without touching how a premium is assembled.
634	    27	 */
635	    28	const HIGHLY_ENCHANTED_FROM = 5;
636	    29	
637	    30	const RISK_RATINGS: readonly RiskRating[] = [
638	    31	  { appliesTo: (item) => item.cursed === true, surchargePercent: 50 },
639	    32	  {
640	    33	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGHLY_ENCHANTED_FROM,
641	    34	    surchargePercent: 30,
642	    35	  },
643	    36	];
644	    37	
645	    38	/** The total item-specific risk surcharge MHPCO charges for one item. */
646	    39	export function itemRiskSurcharge(item: Item): number {
647	    40	  const basePremium = itemBasePremium(item);
648	    41	  return RISK_RATINGS.filter((rating) => rating.appliesTo(item)).reduce(
649	    42	    (total, rating) => total + (basePremium * rating.surchargePercent) / PERCENT,
650	    43	    0,
651	    44	  );
652	    45	}
653	    46	
654	    47	/** The item-specific risk surcharges of all items a policy covers. */
655	    48	export function itemRiskSurcharges(items: readonly Item[]): number {
656	    49	  return items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
